CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE, role TEXT NOT NULL DEFAULT 'investigator' CHECK (role IN ('investigator','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cases (id UUID PRIMARY KEY, case_reference TEXT NOT NULL UNIQUE, fraud_type TEXT NOT NULL, reported_amount NUMERIC(30,8) NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'ETH', reported_wallet_address TEXT, blockchain TEXT NOT NULL DEFAULT 'ethereum', description TEXT, status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','analyzing','under_review','escalated','closed')), analysis_status TEXT NOT NULL DEFAULT 'pending', priority_score INTEGER NOT NULL DEFAULT 0 CHECK (priority_score BETWEEN 0 AND 100), priority_factors JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS wallets (id UUID PRIMARY KEY, address TEXT NOT NULL, chain TEXT NOT NULL, wallet_type TEXT NOT NULL, first_seen_at TIMESTAMPTZ, last_seen_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, UNIQUE(address,chain));
CREATE TABLE IF NOT EXISTS case_wallets (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, wallet_id UUID NOT NULL REFERENCES wallets(id) ON DELETE CASCADE, role TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(case_id,wallet_id));
CREATE TABLE IF NOT EXISTS transactions (id UUID PRIMARY KEY, transaction_hash TEXT NOT NULL, chain TEXT NOT NULL, from_wallet_id UUID NOT NULL REFERENCES wallets(id), to_wallet_id UUID NOT NULL REFERENCES wallets(id), asset TEXT NOT NULL, amount NUMERIC(78,18) NOT NULL, block_number BIGINT, timestamp TIMESTAMPTZ NOT NULL, status TEXT NOT NULL, hop INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(transaction_hash,chain));
CREATE TABLE IF NOT EXISTS case_transactions (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, transaction_id UUID NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL, UNIQUE(case_id,transaction_id));
CREATE TABLE IF NOT EXISTS entities (id UUID PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, verification_status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(name,type));
CREATE TABLE IF NOT EXISTS wallet_entity_labels (id UUID PRIMARY KEY, wallet_id UUID NOT NULL REFERENCES wallets(id), entity_id UUID NOT NULL REFERENCES entities(id), source TEXT NOT NULL, confidence NUMERIC(5,4), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS attributions (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, wallet_id UUID NOT NULL REFERENCES wallets(id), entity_id UUID REFERENCES entities(id), match_type TEXT NOT NULL, confidence NUMERIC(5,4), evidence JSONB, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_results (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, status TEXT NOT NULL, transaction_count INTEGER NOT NULL DEFAULT 0, hop_count INTEGER NOT NULL DEFAULT 0, provider TEXT NOT NULL DEFAULT 'mock', created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS risk_assessments (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 100), level TEXT NOT NULL CHECK (level IN ('low','medium','high','critical')), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS risk_indicators (id UUID PRIMARY KEY, risk_assessment_id UUID NOT NULL REFERENCES risk_assessments(id) ON DELETE CASCADE, code TEXT NOT NULL, description TEXT NOT NULL, severity TEXT NOT NULL, evidence JSONB);
CREATE TABLE IF NOT EXISTS priorities (id UUID PRIMARY KEY, case_id UUID NOT NULL UNIQUE REFERENCES cases(id) ON DELETE CASCADE, priority_score INTEGER NOT NULL CHECK (priority_score BETWEEN 0 AND 100), priority_factors JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS case_relationships (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, related_case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, relationship_type TEXT NOT NULL, confidence NUMERIC(5,4) NOT NULL, evidence JSONB, shared_wallet TEXT, created_at TIMESTAMPTZ NOT NULL, UNIQUE(case_id,related_case_id,relationship_type));
CREATE TABLE IF NOT EXISTS alerts (id UUID PRIMARY KEY, case_id UUID REFERENCES cases(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, severity TEXT NOT NULL, read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, UNIQUE(case_id,type));
CREATE TABLE IF NOT EXISTS investigation_notes (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id), note TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS investigation_reports (id UUID PRIMARY KEY, case_id UUID NOT NULL REFERENCES cases(id) ON DELETE CASCADE, content JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY, case_id UUID REFERENCES cases(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id), action TEXT NOT NULL, details JSONB, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_cases_priority ON cases(priority_score); CREATE INDEX IF NOT EXISTS idx_cases_created ON cases(created_at); CREATE INDEX IF NOT EXISTS idx_wallets_address ON wallets(address); CREATE INDEX IF NOT EXISTS idx_case_relationships_case ON case_relationships(case_id); CREATE INDEX IF NOT EXISTS idx_alerts_created ON alerts(created_at); CREATE INDEX IF NOT EXISTS idx_audit_case ON audit_logs(case_id);
